ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
KB = os.path.join(ROOT, "knowledge", "matrix")
os.makedirs(os.path.join(KB, "energies"), exist_ok=True)
SLUG = {1:"magician",2:"high-priestess",3:"empress",4:"emperor",5:"hierophant",6:"lovers",7:"chariot",8:"justice",9:"hermit",10:"wheel-of-fortune",11:"strength",12:"hanged-man",13:"death",14:"temperance",15:"devil",16:"tower",17:"star",18:"moon",19:"sun",20:"judgement",21:"world",22:"fool"}

SRC_ENERGY = "Авторский синтез Arcana на основе символики Старших арканов и общих описаний 22 энергий в опубликованных разборах Матрицы судьбы (Прибылова, фрагмент книги на LiveLib; Дегтярёва по методу Ладини). Тексты не копируют источники."
energies = []
for n in range(1, 23):
    e = dict(E[n]); e.update(X[n]); e.update(DEEP[n]); e["n"] = n; e["slug"] = SLUG[n]
    e["position_links"] = "Работает во всех точках; особенно значимо в центре (зона комфорта), на линии Неба и Земли, в точках отношений (Р, У, Т) и денег (О, Ф, Т)."
    e["sources"] = ["src.ladini.method", "src.arcana.synthesis"]
    e["confidence"] = {"calculation": "высокая (формулы сверены по числовым примерам)", "interpretation": "средняя: синтез Arcana; сверка с книгой Ладини не выполнена"}
    energies.append(e)
json.dump({"_note": SRC_ENERGY, "energies": energies}, open(os.path.join(KB, "energies.json"), "w"), ensure_ascii=False, indent=1)

