# ---------- Markdown базы знаний ----------
FIELDS = [("strength","В силе"),("shadow","В тени"),("talents","Таланты"),("potential","Потенциал"),("relations","Отношения"),("money","Деньги"),("work","Работа и реализация"),("growth","Личное развитие"),("difficulties","Возможные сложности")]
for e in energies:
    lines = [f"# {e['n']} · {e['name']}", "", f"*{e['short']}*", "", f"**Архетип:** {e['archetype']}  ", f"**Ключевые темы:** {', '.join(e['themes'])}  ", f"**Стиль энергии (для сочетаний):** {e['mode']}", ""]
    for k, t in FIELDS: lines += [f"## {t}", e[k], ""]
    lines += ["## Поведенческий маркер тени", e["shadow_q"], "", "## Бытовой триггер", e["trigger"], "", "## Практика вывода в плюс"] + [f"- {x}" for x in e["practice"]] + ["", "## Признаки «в плюсе»"] + [f"- {x}" for x in e["plus_signs"]] + [""]
    lines += ["## Рекомендации"] + [f"- {x}" for x in e["recommendations"]] + ["", "## Вопросы для рефлексии"] + [f"- {x}" for x in e["questions"]] + ["", "## Связанные позиции Матрицы", e["position_links"], ""]
    if e.get("note"): lines += ["## Примечание", e["note"], ""]
    lines += ["## Источники и уверенность", "- Расчёт позиций: формулы сверены по числовым примерам в опубликованных разборах (см. `sources.md`).", "- Тексты: авторский синтез Arcana, не копия источников. Сверка с книгой Н. Ладини не выполнена.", f"- Подтверждённость интерпретации: {e['confidence']['interpretation']}.", ""]
    open(os.path.join(KB, "energies", f"{e['n']:02d}-{e['slug']}.md"), "w", encoding="utf8").write("\n".join(lines))

def w(name, text): open(os.path.join(KB, name), "w", encoding="utf8").write(text.strip() + "\n")

w("methodology.md", """
# Методика Arcana: Матрица судьбы по системе Наталии Ладини

Arcana использует **одну** методику, не смешивая школы: классическую схему 22 энергий (диагональный и прямой квадраты) по линии Наталии Ладини.
Подробности, решения и расхождения школ: `docs/MATRIX-METHODOLOGY.md`. Проверка: `docs/MATRIX-QA.md`.

Главные решения:
- Числа больше 22 **складываются по цифрам** (23 → 5, 30 → 3). Альтернатива «вычитать 22» отмечена как другая школа и не используется.
- Энергии названы по Старшим арканам Таро в порядке 8 = Справедливость, 11 = Сила, 22 = Шут.
- Интерпретации — авторский синтез Arcana, в языке «в этой системе… может проявляться…».
- Матрица = постоянная карта; Таро = текущий вопрос; Луна = ритм дня; практики = действие. Эти системы не смешиваются математически.
""")
w("calculations.md", """
# Расчёт

Обозначения (кириллические буквы схемы → ключи в коде): А, Б, В, Г, Д, Е, Ж, З, И → `A, B, V, G, D, E, Zh, Z, I`.

```
red(n): пока n > 22 — складываем цифры n (число ≤ 22 не меняется)
A  = red(день)               B = red(месяц)         V = red(сумма цифр года)
G  = red(A+B+V)              D = red(A+B+V+G)       — центр, зона комфорта
E  = A+B   Zh = B+V   Z = V+G   I = G+A            — родовые точки
```
Тройки вдоль линий (внутренняя = внешняя + центр, средняя = внешняя + внутренняя):
```
K = A+D   L = A+K     детско-родительская   (A, L, K)
M = B+D   N = B+M     духовно-творческая    (B, N, M)
O = V+D   P = V+O     материальная          (V, P, O)
R = G+D   S = G+R     кармический хвост     (G, S, R)
T = R+O   U = R+T     любовная              (R, U, T)
F = O+T               денежная              (O, F, T)
Kh = E+D  Ts = E+Kh   род отца, дух         (E, Ts, Kh)
Ch = Zh+D Sh = Zh+Ch  род матери, дух       (Zh, Sh, Ch)
Shch = Z+D  Y = Z+Shch  род отца, материя   (Z, Y, Shch)
Eh = I+D  Yu = I+Eh   род матери, материя   (I, Yu, Eh)
```
Предназначения: Небо = Б+Г; Земля = А+В; личное = Небо+Земля; мужское = Е+З; женское = Ж+И; социальное = мужское+женское; общее = личное+социальное; планетарное = социальное+общее. Сила рода = Е+Ж+З+И; код внутренней силы = сила рода + Д.
Проверка на опубликованных примерах: см. QA.
""")
